20	int sc_main(int argc, char** argv) {
21	  std::vector<char*> v_argv;
22	  for (int i = 0; i < argc; ++i) {
23	    if (std::string(argv[i]) != "--trace") {
24	      v_argv.push_back(argv[i]);
25	    }
26	  }
