33	                    /*debug_axi=*/true, /*instr_trace=*/false,
34	                    /*backdoor_load=*/true,
35	                    /*wfi_cb=*/std::nullopt, std::nullopt);
36	  sc_start(SC_ZERO_TIME);
37	
38	  uint8_t itcm_data[32];
39	  uint8_t dtcm_data[32];
40	  for (int i = 0; i < 32; i++) {
41	    itcm_data[i] = 0xA0 + i;
42	    dtcm_data[i] = 0xB0 + i;
43	  }
44	
45	  tb.BackdoorLoad(0, itcm_data, 32);
46	  tb.BackdoorLoad(0x10000, dtcm_data, 32);
47	
48	  if (absl::GetFlag(FLAGS_trace)) {
49	    tb.trace(tb.core());
50	  }
51	
52	  std::vector<DataTransfer> read_transfers;
53	  read_transfers.push_back(utils::Read(0, 32));
54	  read_transfers.push_back(utils::Expect(itcm_data, 32));
55	  read_transfers.push_back(utils::Read(0x10000, 32));
56	  read_transfers.push_back(utils::Expect(dtcm_data, 32));
57	
58	  tb.EnqueueTransactionAsync(read_transfers);
59	
60	  tb.start();
61	
62	  return 0;
63	}
